import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"VFS 与文件系统家族","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/vfs.md","filePath":"zh/arch/vfs.md"}'),f={name:"zh/arch/vfs.md"};function c(r,e,d,i,h,n){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="vfs-与文件系统家族" tabindex="-1">VFS 与文件系统家族 <a class="header-anchor" href="#vfs-与文件系统家族" aria-label="Permalink to &quot;VFS 与文件系统家族&quot;">​</a></h1><h2 id="vfs-契约" tabindex="-1">VFS 契约 <a class="header-anchor" href="#vfs-契约" aria-label="Permalink to &quot;VFS 契约&quot;">​</a></h2><p><code>fs/fs_vfs.{c,h}</code>：一个 API - open/read/write/seek/close/stat/mkdir/rmdir/readdir/lookup - 适用于已注册的文件系统类型。一种类型注册挂载/卸载钩子以及 file_ops 和 dir_ops。全局节点树透明地解析路径并跨越挂载点。</p><p>实际行为：节点缓存中的大小写敏感（因文件系统而异），强制权限位（模式 0000 被拒绝），按位写访问检查，i64 寻址，拒绝 <code>umount /</code>，无重复子节点的挂载遮蔽，有界的 <code>list_mounts</code>。</p><h2 id="fat32-fs-fs-fat32-c" tabindex="-1">FAT32 (<code>fs/fs_fat32.c</code>) <a class="header-anchor" href="#fat32-fs-fs-fat32-c" aria-label="Permalink to &quot;FAT32 (`fs/fs_fat32.c`)&quot;">​</a></h2><p>支持长文件名（LFN）与别名生成 + 碰撞扫描；读取时进行校验和与序列号验证；跨簇长文件名删除并回溯；维护双 FAT 镜像；读取并维护 FSINFO，并在其中保存下一个空闲簇提示。</p><h2 id="exfat-fs-fs-exfat-c" tabindex="-1">exFAT (<code>fs/fs_exfat.c</code>) <a class="header-anchor" href="#exfat-fs-fs-exfat-c" aria-label="Permalink to &quot;exFAT (`fs/fs_exfat.c`)&quot;">​</a></h2><p>活动 FAT 跟踪、大写表处理、簇链。</p><h2 id="ext4-fs-fs-ext4-c" tabindex="-1">ext4 (<code>fs/fs_ext4.c</code>) <a class="header-anchor" href="#ext4-fs-fs-ext4-c" aria-label="Permalink to &quot;ext4 (`fs/fs_ext4.c`)&quot;">​</a></h2><p>基于扩展区的读写、块组、inode 表。</p><h2 id="ramfs-fs-fs-ramfs-c" tabindex="-1">ramfs (<code>fs/fs_ramfs.c</code>) <a class="header-anchor" href="#ramfs-fs-fs-ramfs-c" aria-label="Permalink to &quot;ramfs (`fs/fs_ramfs.c`)&quot;">​</a></h2><p>易失性根文件系统；稀疏空洞读回时返回零。</p><h2 id="etc-分区" tabindex="-1">/etc 分区 <a class="header-anchor" href="#etc-分区" aria-label="Permalink to &quot;/etc 分区&quot;">​</a></h2><p>一个挂载在 /etc（配置、SSH 密钥、日志、崩溃转储）上的 32 MiB FAT32 镜像 - 由 Makefile 根据 <code>etc/opencube.conf</code> 构建。它是为这个 otherwise in-memory system（内存系统）提供持久化的解决方案。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p><code>fstest</code>（双向断言套件）、<code>fsck</code>、<code>fatstat</code>、<code>fs_mount_test</code>，以及 <code>tests/</code> 中的宿主侧测试工具（使用 ASAN 的 FAT 结构解析）。回归测试套件在每次启动时运行 fstest。</p>',16)])])}const m=a(f,[["render",c]]);export{_ as __pageData,m as default};
